verus! {

    // Element‐wise inequality comparison of two i8‐arrays.
    // Requires equal lengths, returns a Vec<bool> of the same length
    // such that result[i] == (x1[i] != x2[i]).
    fn numpy_not_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool>
        requires
            x1.len() == x2.len(),
        ensures
            result.len() == x1.len(),
        ensures
            forall |i: usize| i < x1.len() ==> result[i] == (x1[i] != x2[i]),
    {
        let n: usize = x1.len();
        let mut idx: usize = 0;
        let mut res: Vec<bool> = Vec::new();
        // Preallocate so pushes never reallocate
        res.reserve(n);

        // Build the result by pushing one boolean per index
        while idx < n
            invariant
                idx <= n,
                res.len() == idx,
                forall |j: usize| j < idx ==> res[j] == (x1[j] != x2[j]),
            decreases n - idx
        {
            let b: bool = x1[idx] != x2[idx];
            res.push(b);
            idx += 1;
        }

        res
    }
}

